#define NQD_TRAP(name, trap, info, selector, result_type)                                   \
    static int carbon_##name(ROMlib_carbon_ppc_frame* call)                                 \
    {                                                                                       \
        uint32_t result;                                                                    \
        if (!ROMlib_carbon_call_original_toolbox_trap(trap, info, selector, call, &result)) \
            return 0;                                                                       \
        call->words[0] = (result_type)result;                                               \
        return 1;                                                                           \
    }
#define NQD_TOOLBOX(name, trap, info, result_type, offset) NQD_TRAP(name, trap, info, 0, result_type)
#define NQD_OFFSCREEN(name, info, selector, result_type, offset) NQD_TRAP(name, 0x31d, info, selector, result_type)
#define NQD_NATIVE(name, handler, offset)
#include "nqd_entries.h"
#undef NQD_OFFSCREEN
#undef NQD_TOOLBOX
#undef NQD_NATIVE
#undef NQD_TRAP

