/* PPC CFM passes a hidden output pointer for a Point result. The 68K
   Toolbox vector returns the same value as a packed longword. */
static int carbon_point_result(ROMlib_carbon_ppc_frame* call, uint32_t vector, uint32_t info, uint32_t selector)
{
    void* output = call->words[0] ? ROMlib_carbon_guest_memory(call->words[0], sizeof(uint32_t), 1) : NULL;
    if (!output)
        return 0;
    ROMlib_carbon_ppc_frame arguments = {0};
    arguments.words[0] = call->words[1];
    arguments.words[1] = call->words[2];
    uint32_t point;
    if (!ROMlib_carbon_call_toolbox_vector(vector, info, selector, &arguments, &point))
        return 0;
    point = CL(point);
    memcpy(output, &point, sizeof point);
    return 1;
}

static int carbon_LLastClick(ROMlib_carbon_ppc_frame* call)
{
    return carbon_point_result(call, 0x159c, 0x3be, 0x40);
}

static int carbon_TEGetPoint(ROMlib_carbon_ppc_frame* call)
{
    return carbon_point_result(call, 0x0ef4, 0xebe, 0x08);
}

static int carbon_text_edit(ROMlib_carbon_ppc_frame* call, const char* name, unsigned handle_argument, uint32_t vector,
                            uint32_t info, uint32_t selector)
{
    enum { text_services_flag = 0x80 };

    const uint32_t handle = call->words[handle_argument];
    uint32_t record = 0, private_handle = 0, private_record = 0, flags = 0;
    if (handle &&
        (!cfp_get(handle, &record) || (record && !cfp_get(record + offsetof(TERec, recalBack), &private_handle)) ||
         (private_handle && !cfp_get(private_handle, &private_record)) ||
         (private_record && !cfp_get(private_record + offsetof(tehidden, flags), &flags))))
        return 0;

    if ((flags & text_services_flag) || (selector == 0x0e && (int16_t)call->words[0] != teFAutoScroll)) {
        ROMlib_carbon_reference saved;
        if (ROMlib_carbon_probe_reference("CarbonLib", name, &saved))
            return ROMlib_carbon_invoke_frame(saved.function, call);
    }

    uint32_t result;
    if (!ROMlib_carbon_call_toolbox_vector(vector, info, selector, call, &result))
        return 0;
    call->words[0] = selector ? (uint32_t)(int32_t)(int16_t)result : result;
    return 1;
}

#define CARBON_TEXT_EDIT(name, handle_argument, vector, info, selector)                \
    static int carbon_##name(ROMlib_carbon_ppc_frame* call)                            \
    {                                                                                  \
        return carbon_text_edit(call, #name, handle_argument, vector, info, selector); \
    }

