static int dispose_carbon_window(ROMlib_carbon_ppc_frame* call)
{
    const uint32_t window = call->words[0];
    if (!carbon_vector_DisposeWindow(call))
        return 0;
    if (window)
        ROMlib_carbon_drag_forget_window(window);
    return 1;
}

static int carbon_DisposeWindow(ROMlib_carbon_ppc_frame* call)
{
    uint32_t owners, status;
    if (!ROMlib_carbon_window_owners(call->words[0], -1, &owners, &status))
        return 0;
    if ((int32_t)status == -5600)
        return dispose_carbon_window(call);
    if (status)
        return ROMlib_carbon_report_failure("Could not release Carbon window owner");
    return owners || dispose_carbon_window(call);
}

static int carbon_window_lifetime(ROMlib_carbon_ppc_frame* call, int change, const char* name, uint32_t offset)
{
    ROMlib_carbon_reference saved;
    if (ROMlib_carbon_probe_reference("CarbonLib", name, &saved) &&
        (saved.code_offset != offset || saved.code_size != 0xb8fb4 || saved.toc_offset != 0x2f78 ||
         saved.toc_size != 0x10f0c))
        return ROMlib_carbon_invoke_frame(saved.function, call);
    uint32_t owners, status;
    if (!ROMlib_carbon_window_owners(call->words[0], change, &owners, &status))
        return 0;
    if (change < 0 && !status && !owners && !dispose_carbon_window(call))
        return 0;
    call->words[0] = change ? status : status ? 0 : owners;
    return 1;
}

static int carbon_GetWindowRetainCount(ROMlib_carbon_ppc_frame* call)
{
    return carbon_window_lifetime(call, 0, "GetWindowRetainCount", 0x13584);
}

static int carbon_RetainWindow(ROMlib_carbon_ppc_frame* call)
{
    return carbon_window_lifetime(call, 1, "RetainWindow", 0x135b8);
}

static int carbon_CloneWindow(ROMlib_carbon_ppc_frame* call)
{
    return carbon_window_lifetime(call, 1, "CloneWindow", 0x13448);
}

static int carbon_ReleaseWindow(ROMlib_carbon_ppc_frame* call)
{
    return carbon_window_lifetime(call, -1, "ReleaseWindow", 0x135dc);
}

static int carbon_SetWTitle(ROMlib_carbon_ppc_frame* call)
{
    const uint32_t window = call->words[0];
    return carbon_vector_SetWTitle(call) && ROMlib_carbon_clear_window_title(window);
}

/* ROMAW exposes one PowerPC processor. MPLibrary reports one installed
   and one scheduled processor even when its nanokernel is unavailable. */
static uint32_t carbon_mp_processor_count(void)
{
    return 1;
}

static uint32_t carbon_GZSaveHnd(void)
{
    return cfp_read(0x328);
}

static int16_t carbon_GetDefFontSize(void)
{
    const int16_t size = ROMlib_carbon_LMGetSysFontSize();
    return size ? size : 12;
}

static uint32_t carbon_SetA5(uint32_t value)
{
    const uint32_t previous = EM_A5;
    EM_A5 = value;
    return previous;
}

static uint32_t carbon_SetCurrentA5(void)
{
    return carbon_SetA5(CL((uint32_t)(uintptr_t)CurrentA5));
}

static int carbon_MPDataToCode(ROMlib_carbon_ppc_frame* call)
{
    return ROMlib_carbon_call_romaw_service("MakeDataExecutable", call);
}

